public class ImageFlipTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String rowText(java.awt.image.BufferedImage img, int y) {
        if (img == null) {
            return "(null image)";
        }
        StringBuilder sb = new StringBuilder();
        for (int x = 0; x < img.getWidth(); x++) {
            if (x > 0) {
                sb.append(' ');
            }
            sb.append(String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF));
        }
        return sb.toString();
    }

    static String size(java.awt.image.BufferedImage img) {
        if (img == null) {
            return "(null image)";
        }
        return img.getWidth() + "x" + img.getHeight();
    }

    static java.awt.image.BufferedImage makeSource() {
        java.awt.image.BufferedImage src =
                new java.awt.image.BufferedImage(3, 2, java.awt.image.BufferedImage.TYPE_INT_RGB);
        int[][] pixels = {
                {0x220000, 0x331111, 0x442222},
                {0x553333, 0x664444, 0x775555}
        };
        for (int y = 0; y < 2; y++) {
            for (int x = 0; x < 3; x++) {
                src.setRGB(x, y, pixels[y][x]);
            }
        }
        return src;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage src = makeSource();
            String row0 = rowText(src, 0);
            String row1 = rowText(src, 1);

            java.awt.image.BufferedImage horiz = ImageFlip.flipHorizontal(src);
            check("flipHorizontal keeps the size", "3x2", size(horiz));
            check("flipHorizontal row 0", "#442222 #331111 #220000", rowText(horiz, 0));
            check("flipHorizontal row 1", "#775555 #664444 #553333", rowText(horiz, 1));
            check("flipHorizontal returns a new image", true, horiz != null && horiz != src);

            java.awt.image.BufferedImage vert = ImageFlip.flipVertical(src);
            check("flipVertical keeps the size", "3x2", size(vert));
            check("flipVertical row 0 is the old row 1", row1, rowText(vert, 0));
            check("flipVertical row 1 is the old row 0", row0, rowText(vert, 1));

            java.awt.image.BufferedImage twice = ImageFlip.flipHorizontal(ImageFlip.flipHorizontal(src));
            check("flipping horizontally twice restores row 0", row0, rowText(twice, 0));

            check("src row 0 unchanged", "#220000 #331111 #442222", rowText(src, 0));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

